                continue
            votes = {}
            for dr in range(-h + 1, h):
                for dc in range(-w + 1, w):
                    rr, cc = r + dr, c + dc
                    if not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] == 6:
                        continue
                    score = 0
                    for dy in range(-4, 5):
                        for dx in range(-4, 5):
                            y, x = r + dy, c + dx
                            yy, xx = y + dr, x + dc
                            if (0 <= y < h and 0 <= x < w and
